let s1 = String::from("hello");
let s2 = s1;          // s1 est "déplacé" dans s2
// println!("{s1}");   // ERREUR : s1 n'est plus valide
println!("{s2}");      // OK

fn longueur(s: &String) -> usize {
    s.len()            // on lit sans prendre possession
}

let s = String::from("hello");
let n = longueur(&s);  // s reste utilisable ici
println!("{s} fait {n}");
